$manifest = ($global:memList.items | Where-Object id -eq 'MEMORY-PROFILE-000').text | ConvertFrom-Json
$global:profileParts = [ordered]@{}
$results = foreach ($p in $manifest.parts) {
  $item = $global:memList.items | Where-Object id -eq $p.id
  if (-not $item) { [pscustomobject]@{ id=$p.id; status='MISSING' }; continue }
  $snap = $item.text | ConvertFrom-Json
  $bytes = [Convert]::FromBase64String($snap.dataBase64)
  $hash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes))
  $ok = ($hash -ceq $snap.sourceSha256) -and ($hash -ceq $p.sourceSha256)
  $global:profileParts[$p.id] = [pscustomobject]@{ id=$p.id; sourceName=$snap.sourceName; text=[Text.Encoding]::UTF8.GetString($bytes) }
  [pscustomobject]@{ id=$p.id; src=$p.sourceName; fmt=$snap.profileFormat; enc=$snap.encoding; snapName=$snap.sourceName; bytes=$bytes.Length; hashOk=$ok; textEqContent=($item.text -ceq $item.content); ver=$item.version }
}
$results | Format-Table -AutoSize | Out-String -Width 250
"Verified: $(@($results | Where-Object hashOk).Count) / $($manifest.parts.Count)"
# Additional profile entries not in manifest?
$extra = $global:memList.items | Where-Object { $_.id -like 'MEMORY-PROFILE-*' -and $_.id -ne 'MEMORY-PROFILE-000' -and ($manifest.parts.id -notcontains $_.id) }
"Extra profile entries not in manifest: $(@($extra).Count)"

