2	[CmdletBinding()]
3	param(
4	    [ValidateSet('Status', 'Invoke', 'CompleteTurn')]
5	    [string]$Command = 'Status',
6	
7	    [string]$Method,
8	
9	    [string]$Params,
10	
11	    [string]$ParamsPath,
12	
13	    [object]$ParamsObject,
14	
