21	    [string]$PluginRoot = $(if ($env:MCP_PLUGIN_ROOT) { $env:MCP_PLUGIN_ROOT } elseif ($env:CLAUDE_PLUGIN_ROOT) { $env:CLAUDE_PLUGIN_ROOT } else { Split-Path -Parent $PSScriptRoot }),
22	
23	    [string]$CacheRoot,
24	
25	    [int]$TimeoutSeconds = $(if ($env:MCP_PLUGIN_TIMEOUT_SECONDS) { [int]$env:MCP_PLUGIN_TIMEOUT_SECONDS } else { 90 })
26	)
27	
28	Set-StrictMode -Version Latest
29	$ErrorActionPreference = 'Stop'
30	
31	$shimModule = Join-Path $PSScriptRoot 'McpPluginShim.psm1'
32	Import-Module $shimModule -ErrorAction Stop
33	. (Join-Path $PSScriptRoot 'yaml-object-mutation.ps1')
34	
35	$script:McpPluginParamsObjectBound = $PSBoundParameters.ContainsKey('ParamsObject')
36	if ($script:McpPluginParamsObjectBound -and ($PSBoundParameters.ContainsKey('Params') -or $PSBoundParameters.ContainsKey('ParamsPath'))) {
37	    throw '-ParamsObject cannot be combined with -Params or -ParamsPath.'
38	}
39	
40	$script:McpPluginParamsFromObject = ''
41	if ($script:McpPluginParamsObjectBound) {
42	    Import-McpYamlSerializer
43	    $script:McpPluginParamsFromObject = ConvertTo-Yaml -Data $ParamsObject -Options WithIndentedSequences
44	}
45	
46	function Resolve-McpPluginDefaultWorkspacePath {
47	    $current = (Get-Location).ProviderPath
48	    if ($current) {
49	        $dir = $current
50	        for ($i = 0; $i -lt 20 -and $dir; $i++) {
51	            $marker = Join-Path $dir 'AGENTS-README-FIRST.yaml'
52	            if (Test-Path -LiteralPath $marker -PathType Leaf) {
53	                return (Resolve-Path -LiteralPath $dir).ProviderPath
54	            }
55	
56	            $parent = Split-Path -Parent $dir
57	            if ($parent -eq $dir) { break }
58	            $dir = $parent
59	        }
60	    }
61	
62	    $configured = @(
63	        $env:MCP_WORKSPACE_PATH,
64	        $env:MCPSERVER_WORKSPACE_PATH,
65	        $env:CODEX_WORKSPACE_PATH,
66	        $env:CODEX_PROJECT_DIR,
67	        $env:CLAUDE_PROJECT_DIR
68	    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_ -PathType Container) } | Select-Object -First 1
69	
70	    if ($configured) { return (Resolve-Path -LiteralPath $configured).ProviderPath }
71	    return $current
72	}
73	
74	$script:McpPluginWorkspacePathExplicit = $PSBoundParameters.ContainsKey('WorkspacePath')
75	if (-not $script:McpPluginWorkspacePathExplicit -or [string]::IsNullOrWhiteSpace($WorkspacePath)) {
76	    $WorkspacePath = Resolve-McpPluginDefaultWorkspacePath
77	}
78	
79	$script:McpPluginInvocation = New-McpPluginInvocationOptions `
80	    -Command $Command `
81	    -Method ($Method ?? '') `
82	    -Params $(if ($script:McpPluginParamsObjectBound) { $script:McpPluginParamsFromObject } else { $Params ?? '' }) `
83	    -ParamsPath ($ParamsPath ?? '') `
84	    -ParamsObject $(if ($script:McpPluginParamsObjectBound) { $ParamsObject } else { $null }) `
85	    -Response ($Response ?? '') `
86	    -ResponsePath ($ResponsePath ?? '') `
87	    -WorkspacePath $WorkspacePath `
88	    -PluginRoot $PluginRoot `
89	    -CacheRoot ($CacheRoot ?? '') `
90	    -TimeoutSeconds $TimeoutSeconds
