92	function Resolve-FullPath {
93	    param([Parameter(Mandatory)][string]$Path)
94	
95	    $resolved = Resolve-Path -LiteralPath $Path -ErrorAction Stop
96	    return $resolved.ProviderPath
97	}
98	
99	function Resolve-OptionalDirectory {
100	    param([Parameter(Mandatory)][string]$Path)
101	
102	    if (-not (Test-Path -LiteralPath $Path)) {
103	        [void][System.IO.Directory]::CreateDirectory($Path)
104	    }
105	
106	    return (Resolve-FullPath $Path)
107	}
108	
109	function Read-RedirectedInput {
110	    if ([Console]::IsInputRedirected) {
111	        return [Console]::In.ReadToEnd()
112	    }
113	
114	    return ''
115	}
116	
117	function Read-OptionalText {
118	    param(
119	        [string]$Inline,
120	        [bool]$HasInline,
121	        [string]$Path,
122	        [switch]$AllowRedirectedInput
123	    )
124	
125	    if ($Path) {
126	        return [System.IO.File]::ReadAllText((Resolve-FullPath $Path))
127	    }
128	
129	    if ($HasInline) {
130	        return $Inline
131	    }
132	
133	    if ($AllowRedirectedInput) {
134	        return (Read-RedirectedInput)
135	    }
136	
137	    return ''
138	}
