140	function Resolve-PluginPowerShellScript {
141	    param(
142	        [Parameter(Mandatory)][string]$Root,
143	        [Parameter(Mandatory)][string]$Name
144	    )
145	
146	    foreach ($libName in @('lib', 'lib-ps')) {
147	        $candidate = Join-Path (Join-Path $Root $libName) $Name
148	        if (Test-Path -LiteralPath $candidate) {
149	            return $candidate
150	        }
151	    }
152	
153	    throw "Unable to find plugin PowerShell script '$Name' under '$Root'."
154	}
155	
156	function Resolve-McpPluginHostName {
157	    param([Parameter(Mandatory)][string]$Root)
158	
159	    $normalizedRoot = $Root.Replace('\\', '/').ToLowerInvariant()
160	    switch -Regex ($normalizedRoot) {
161	        'mcpserver-claude-cowork-plugin|claude-cowork' { return 'claude-cowork' }
162	        'mcpserver-claude-code-plugin|claude-code' { return 'claude-code' }
163	        'mcpserver-codex-plugin|/codex(?:/|$)' { return 'codex' }
164	        'mcpserver-copilot-plugin|/copilot(?:/|$)' { return 'copilot' }
165	        'mcpserver-grok-plugin|/grok(?:/|$)' { return 'grok' }
166	        'mcpserver-cline-v2-plugin|cline-v2' { return 'cline-v2' }
167	        'mcpserver-cline-plugin|/cline(?:/|$)' { return 'cline' }
168	        'mcpserver-opencode-plugin|open-code|opencode' { return 'opencode' }
169	    }
170	
171	    return ''
172	}
173	
174	function Get-McpPluginHostDefaults {
175	    param([Parameter(Mandatory)][string]$HostName)
176	
177	    switch ($HostName.Trim().ToLowerInvariant()) {
178	        { $_ -in 'claude', 'claude-code' } {
179	            return [ordered]@{ Host = 'claude-code'; Agent = 'ClaudeCode'; Model = 'claude'; Tag = 'claude-code' }
180	        }
181	        { $_ -in 'cowork', 'claude-cowork' } {
182	            return [ordered]@{ Host = 'claude-cowork'; Agent = 'ClaudeCowork'; Model = 'claude'; Tag = 'claude-cowork' }
183	        }
184	        'codex' {
185	            return [ordered]@{ Host = 'codex'; Agent = 'Codex'; Model = 'codex'; Tag = 'codex' }
186	        }
187	        'copilot' {
188	            return [ordered]@{ Host = 'copilot'; Agent = 'Copilot'; Model = 'copilot'; Tag = 'copilot' }
189	        }
190	        'grok' {
191	            return [ordered]@{ Host = 'grok'; Agent = 'GrokCode'; Model = 'grok'; Tag = 'grok' }
192	        }
193	        'cline' {
194	            return [ordered]@{ Host = 'cline'; Agent = 'Cline'; Model = 'cline'; Tag = 'cline' }
195	        }
196	        'cline-v2' {
197	            return [ordered]@{ Host = 'cline-v2'; Agent = 'Cline'; Model = 'cline'; Tag = 'cline-v2' }
198	        }
199	        { $_ -in 'opencode', 'open-code' } {
200	            return [ordered]@{ Host = 'opencode'; Agent = 'OpenCode'; Model = 'opencode'; Tag = 'opencode' }
201	        }
202	    }
203	
204	    return $null
