        {
          "id": "ac-04",
          "text": "Use the same recording byte/error traces as FR-RUNTIME-TAPE-002 ac-06. Preserve the pinned native first-write handling and encoded gap behavior, including known native quirks, without patching VICE or replacing expected values with managed output.",
          "isSatisfied": false
        }
      ],
