function global:Canon($x) { $x | ConvertTo-Json -Depth 100 -Compress }
function global:DiffColl($name, $before, $after, [scriptblock]$keyFn) {
  $bm = @{}; foreach ($r in $before) { $k = & $keyFn $r; if ($bm.ContainsKey($k)) { "DUPKEY before $name $k" }; $bm[$k] = $r }
  $am = @{}; foreach ($r in $after) { $k = & $keyFn $r; if ($am.ContainsKey($k)) { "DUPKEY after $name $k" }; $am[$k] = $r }
  $added = @($am.Keys | Where-Object { -not $bm.ContainsKey($_) })
  $removed = @($bm.Keys | Where-Object { -not $am.ContainsKey($_) })
  $changed = @($bm.Keys | Where-Object { $am.ContainsKey($_) -and (Canon $bm[$_]) -cne (Canon $am[$_]) })
  "[$name] before=$($bm.Count) after=$($am.Count) added=$($added.Count) removed=$($removed.Count) changed=$($changed.Count)"
  foreach ($k in $added) { "  ADDED $k" }; foreach ($k in $removed) { "  REMOVED $k" }
  foreach ($k in $changed) {
    $b = $bm[$k]; $a = $am[$k]
    $props = @($b.PSObject.Properties.Name) + @($a.PSObject.Properties.Name) | Sort-Object -Unique
    $diffs = foreach ($p in $props) { $bv = if ($b.PSObject.Properties[$p]) { Canon $b.$p } else { '<absent>' }; $av = if ($a.PSObject.Properties[$p]) { Canon $a.$p } else { '<absent>' }; if ($bv -cne $av) { $p } }
    "  CHANGED $k fields=[$($diffs -join ',')]"
  }
}
