function global:FindRec($eff, $id) { foreach ($c in 'functional','technical','testing') { $r = $eff.$c | Where-Object id -eq $id; if ($r) { return $r } } }
$res = foreach ($d in $global:delta) {
  $b = FindRec $global:effB $d.id; $a = FindRec $global:effA $d.id
  $cf = if ($d.kind -eq 'test') { 'condition' } else { 'body' }
  $acB = Canon @($b.acceptanceCriteria); $acDB = Canon @($d.before.acceptanceCriteria)
  $acA = Canon @($a.acceptanceCriteria); $acDP = Canon @($d.proposed.acceptanceCriteria)
  [pscustomobject]@{
    id = $d.id
    beforeContentEq = ($b.$cf -ceq $d.before.content)
    beforeStatusEq = ($b.status -ceq $d.before.status)
    beforeAcEq = ($acB -ceq $acDB)
    beforeTitleEq = if ($d.before.PSObject.Properties['title']) { $b.title -ceq $d.before.title } else { 'n/a' }
    afterContentEq = ($a.$cf -ceq $d.proposed.content)
    afterStatusEq = ($a.status -ceq $d.proposed.status)
    afterAcEq = ($acA -ceq $acDP)
    afterTitleEq = if ($d.proposed.PSObject.Properties['title']) { $a.title -ceq $d.proposed.title } else { ($a.title -ceq $b.title) }
    acCount = @($a.acceptanceCriteria).Count
    anySatisfied = @($a.acceptanceCriteria | Where-Object { $_.isSatisfied -ne $false }).Count
    keysBefore = ($b.PSObject.Properties.Name -join ',')
    keysAfter = ($a.PSObject.Properties.Name -join ',')
  }
}
$res | Format-List | Out-String -Width 300
"Total AC after: $(($res | Measure-Object acCount -Sum).Sum); any satisfied: $(($res | Measure-Object anySatisfied -Sum).Sum)"

