449	    if (((datasette_tape_wobble_frequency == 0) || (datasette_tape_wobble_amplitude == 0)) &&
450	        (datasette_speed_tuning == 0)) {
451	        return gap;
452	    }
453	
454	    /* convert resource values to floats */
455	    freq = (float)datasette_tape_wobble_frequency / (float)TAP_WOBBLE_FREQ_ONE;
456	    amplitude = (float)datasette_tape_wobble_amplitude / (float)TAP_WOBBLE_AMPLITUDE_ONE;
457	    tuning = (float)datasette_speed_tuning / (float)TAP_SPEED_TUNING_ONE;
