504	inline static int fetch_gap(int port, CLOCK *gap, int *direction, long read_tap)
505	{
506	    if ((read_tap >= last_tap[port]) || (read_tap < 0)) {
507	        return -1;
508	    }
509	
510	    *gap = tap_buffer[port][read_tap];
511	
512	    if ((current_image[port]->version == 0) || *gap) {
513	        /* in v0 tap files gaps > 255 produced an overflow and generally
514	           produced 0 - which needs to be reinterpreted as a "long" gap.
515	           "mtap" by Marcus Brenner, which probably the majority of tap v0 files
516	           are created with, uses 2500.
517	           We also add a constant number of cycles (default:1) to compensate
518	           for tape speed variations. */
519	        *gap = (*gap ? (CLOCK)(*gap * 8) : (CLOCK)datasette_zero_gap_delay);
520	    } else {
521	        if (read_tap >= last_tap[port] - 3) {
522	            return -1;
523	        }
524	        *direction *= 4;
525	        *gap = tap_buffer[port][read_tap + 1]
526	               + (tap_buffer[port][read_tap + 2] << 8)
527	               + (tap_buffer[port][read_tap + 3] << 16);
528	        if (!(*gap)) {
529	            *gap = (CLOCK)datasette_zero_gap_delay;
530	        }
531	    }
532	
533	    *gap = tape_do_wobble(port, *gap);
534	    *gap = tape_do_misalignment(*gap);
535	    return 0;
536	}
